#include <DHT.h>  // DHT sensor library by Adafruit
#include <math.h>

#define DHT_PIN 12
#define DHT_TYP DHT11
DHT dht(DHT_PIN, DHT_TYP);

// Bity: a b c d e f g (bit 0 = a, bit 6 = g)
const byte cyfry[10] = {63, 6, 91, 79, 102, 109, 125, 7, 127, 111};

int minimum, maksimum;
int jasnosc = 0, wilgotnosc = 0, temperatura = 0;
byte tryb = 0;  // 0 = jasnosc (L), 1 = wilgotnosc (H), 2 = temperatura (t)

unsigned long ostatnieSwiatlo = 0, ostatniDHT = 0;
unsigned long czasZmiany = 0, czasEtykiety = 0;
bool poprzedniOdczyt = HIGH, stanPrzycisku = HIGH;
bool pokazEtykiete = false;

void segmenty(byte wzor) {
  for (int i = 0; i < 7; i++)
    digitalWrite(i + 2, bitRead(wzor, i) ? LOW : HIGH);
}

void cyfra(int n) {
  segmenty(cyfry[n]);
}

void wyswietl(int liczba) {
  liczba = constrain(liczba, 0, 99);
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);
  cyfra(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);
  cyfra(liczba / 10);
  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);
}

// Wyswietl litere na lewej cyfrze (prawej nie zapalamy):
// L = jasnosc, H = wilgotnosc, t = temperatura.
void wyswietlLitere() {
  byte wzor;
  if (tryb == 0)      wzor = 0b00111000;  // L: d, e, f
  else if (tryb == 1) wzor = 0b01110110;  // H: b, c, e, f, g
  else                wzor = 0b01111000;  // t: d, e, f, g

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);
  segmenty(wzor);
  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);
  delay(2);
}

void pomiary() {
  unsigned long teraz = millis();
  if (teraz - ostatnieSwiatlo >= 400) {
    ostatnieSwiatlo = teraz;
    int wartosc = analogRead(A0);
    if (wartosc < minimum) minimum = wartosc;
    if (wartosc > maksimum) maksimum = wartosc;
    if (maksimum > minimum)
      jasnosc = 99L * (wartosc - minimum) / (maksimum - minimum);
  }
  if (teraz - ostatniDHT >= 2000) {
    ostatniDHT = teraz;
    float h = dht.readHumidity();
    float t = dht.readTemperature();
    if (!isnan(h)) wilgotnosc = (int)(h + 0.5);
    if (!isnan(t)) temperatura = (int)(t + (t >= 0 ? 0.5 : -0.5));
  }
}

void przycisk() {
  bool odczyt = digitalRead(9); // INPUT_PULLUP: wcisniety = LOW
  if (odczyt != poprzedniOdczyt) czasZmiany = millis();
  if (millis() - czasZmiany >= 40 && odczyt != stanPrzycisku) {
    stanPrzycisku = odczyt;
    if (stanPrzycisku == LOW) {
      tryb = (tryb + 1) % 3;
      czasEtykiety = millis();
      pokazEtykiete = true;
    }
  }
  poprzedniOdczyt = odczyt;
}

void setup() {
  for (int i = 2; i <= 8; i++) pinMode(i, OUTPUT);
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);
  pinMode(9, INPUT_PULLUP);
  dht.begin();
  minimum = maksimum = analogRead(A0);
}

void loop() {
  pomiary();
  przycisk();

  if (pokazEtykiete && millis() - czasEtykiety < 1000) {
    wyswietlLitere();
  } else {
    pokazEtykiete = false;
    int liczba = (tryb == 0) ? jasnosc : (tryb == 1 ? wilgotnosc : temperatura);
    wyswietl(liczba);
  }
}
